import{_t as e,it as t,n,rt as r}from"./chunks/framework.DaD4z1Q-.js";var i=JSON.parse(`{"title":"Why prefix Composer dependencies in Wordpress","description":"Two Wordpress plugins that bundle different versions of the same library can break each other. See how namespace prefixing stops the clash.","frontmatter":{"title":"Why prefix Composer dependencies in Wordpress","description":"Two Wordpress plugins that bundle different versions of the same library can break each other. See how namespace prefixing stops the clash."},"headers":[],"relativePath":"guide/why.md","filePath":"guide/why.md"}`),a={name:`guide/why.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="why-prefix" tabindex="-1">Why prefix? <a class="header-anchor" href="#why-prefix" aria-label="Permalink to “Why prefix?”">​</a></h1><p>Say two plugins bundle different versions of the same library. Wordpress loads both into one PHP process, so whichever autoloader registers first wins and the other plugin gets the wrong version.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wp-content/plugins/</span></span>
<span class="line"><span>├── plugin-a/</span></span>
<span class="line"><span>│   ├── plugin-a.php</span></span>
<span class="line"><span>│   └── vendor/</span></span>
<span class="line"><span>│       └── guzzlehttp/guzzle/     # v6.5, declares GuzzleHttp\\Client</span></span>
<span class="line"><span>└── plugin-b/</span></span>
<span class="line"><span>    ├── plugin-b.php</span></span>
<span class="line"><span>    └── vendor/</span></span>
<span class="line"><span>        └── guzzlehttp/guzzle/     # v7.8, also declares GuzzleHttp\\Client</span></span></code></pre></div><p>Plugin B can end up calling v6.5 code it was never tested with, or PHP can stop with a &quot;cannot redeclare class&quot; error. Which one you get depends on plugin load order.</p><p>Strauss-RS copies each dependency into a folder of its own and renames its namespaces and global symbols with a prefix that belongs to your plugin. After running it in each plugin, every copy lives under its own name:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wp-content/plugins/</span></span>
<span class="line"><span>├── plugin-a/</span></span>
<span class="line"><span>│   ├── plugin-a.php</span></span>
<span class="line"><span>│   └── vendor-prefixed/</span></span>
<span class="line"><span>│       └── guzzlehttp/guzzle/     # Acme\\PluginA\\Vendor\\GuzzleHttp\\Client (v6.5)</span></span>
<span class="line"><span>└── plugin-b/</span></span>
<span class="line"><span>    ├── plugin-b.php</span></span>
<span class="line"><span>    └── vendor-prefixed/</span></span>
<span class="line"><span>        └── guzzlehttp/guzzle/     # Acme\\PluginB\\Vendor\\GuzzleHttp\\Client (v7.8)</span></span></code></pre></div><p>The two copies no longer share a name, so they no longer clash.</p><h2 id="what-gets-renamed" tabindex="-1">What gets renamed <a class="header-anchor" href="#what-gets-renamed" aria-label="Permalink to “What gets renamed”">​</a></h2><ul><li>Namespaces: <code>GuzzleHttp\\Client</code> becomes <code>Acme\\PluginA\\Vendor\\GuzzleHttp\\Client</code>.</li><li>Classes, interfaces, traits and enums in the global namespace: <code>Parsedown</code> becomes <code>Acme_PluginA_Parsedown</code>.</li><li>Global functions: <code>mb_helper()</code> becomes <code>acme_plugina_mb_helper()</code>.</li><li>Constants, if you set a <code>constant_prefix</code>.</li></ul><p>Every place that refers to one of those names is updated too: <code>use</code> statements, type hints, docblocks, and class names written inside strings.</p><h2 id="where-it-comes-from" tabindex="-1">Where it comes from <a class="header-anchor" href="#where-it-comes-from" aria-label="Permalink to “Where it comes from”">​</a></h2><p>Strauss-RS is a port of <a href="https://github.com/BrianHenryIE/strauss" target="_blank" rel="noreferrer">Strauss</a> by Brian Henry, which is itself a fork of Mozart. It is written in Rust and runs as a single binary, so it needs no PHP to run. It reads the same kinds of settings Strauss PHP does, with a few differences listed on the <a href="./migrating.html">migration page</a>.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};